import { mount, signal } from 'kerfjs';
import { delegateActions } from 'kerfjs/actions';
import { Toolbar } from '@kerfjs/ui/toolbar';
import { ToolbarText } from '@kerfjs/ui/toolbar-text';
import { ToolbarControlGroup } from '@kerfjs/ui/toolbar-control-group';
import { MenuHeader } from '@kerfjs/ui/menu-header';
import { MenuItem } from '@kerfjs/ui/menu-item';
import { PageHeader } from '@kerfjs/ui/page-header';
import { ValueTable } from '@kerfjs/ui/value-table';
import { ResizableRegion } from '@kerfjs/ui/resizable-region';
import { wireResizableRegions } from '@kerfjs/ui/wire-resizable-regions';
import '@kerfjs/ui/layout.css';
import '@kerfjs/ui/sidebar.css';
import './shell.css';

export function mountShell(root: HTMLElement, app: { initialInspectorSize: number; saveInspectorSize(size: number): void; navigate(id: string): void }) {
 const selected = signal('inbox');
 const size = signal(Math.max(200, Math.min(360, app.initialInspectorSize || 240)));
 const phone = signal(matchMedia('(max-width: 48rem)').matches);
 const pane = signal('workspace');
 const media = matchMedia('(max-width: 48rem)');
 const changed = () => { phone.value = media.matches; };
 media.addEventListener('change', changed);
 const navigation = () => <nav class="shell-nav kui-sidebar kui-scroll-owner" aria-label="Workspace navigation">
  <section class="kui-sidebar-section"><MenuHeader label="Workspace" />{['inbox', 'projects'].map(id => <MenuItem action="navigate" itemId={id} label={id === 'inbox' ? 'Inbox' : 'Projects'} selected={selected.value === id} />)}</section>
  <section class="kui-sidebar-section"><MenuHeader label="Organization" /><MenuItem action="navigate" itemId="people" label="People" selected={selected.value === 'people'} /></section>
 </nav>;
 const inspector = () => <aside class="shell-pane"><PageHeader title="Inspector" /><div class="kui-pane-body kui-scroll-owner"><ValueTable label="Selection"><div><dt>Section</dt><dd>{selected.value}</dd></div></ValueTable></div></aside>;
 const stopMount = mount(root, () => <div class="shell kui-layout">
  <Toolbar label="Application" leading={<ToolbarText text="Workspace" />} trailing={<ToolbarControlGroup label="Visible pane">{['navigation','workspace','inspector'].map(id => <button type="button" data-action="pane" data-pane={id} aria-pressed={String(pane.value === id)}>{id}</button>)}</ToolbarControlGroup>} />
  <div class="shell-body">
   {(!phone.value || pane.value === 'navigation') && navigation()}
   {(!phone.value || pane.value === 'workspace') && <main class="shell-pane shell-main"><PageHeader title={selected.value} /><div class="kui-pane-body kui-section-stack kui-scroll-owner"><h2>Workspace</h2><p>Your application content appears here.</p></div></main>}
   {phone.value ? pane.value === 'inspector' && inspector() : <ResizableRegion id="inspector" label="Inspector width" size={size.value} min={200} max={360} edge="start">{inspector()}</ResizableRegion>}
  </div>
 </div>);
 const stopActions = delegateActions(root, 'click', {
  pane: (_e, el) => { pane.value = (el as HTMLElement).dataset.pane!; },
  navigate: (_e, el) => { const id = (el as HTMLElement).dataset.itemId!; selected.value = id; app.navigate(id); if (phone.value) { pane.value = 'workspace'; queueMicrotask(() => root.querySelector<HTMLElement>('main h2')?.focus()); } }
 });
 const stopResize = wireResizableRegions(root, { onCommit: change => { size.value = change.size; app.saveInspectorSize(change.size); } });
 return () => { stopResize(); stopActions(); stopMount(); media.removeEventListener('change', changed); };
}

