.shell { height: 100dvh; min-width: 0; display: grid; grid-template-rows: auto minmax(0,1fr); color: var(--kui-color-text); background: var(--kui-color-surface); overflow: hidden; }
.shell-body { display: flex; min-height: 0; min-width: 0; }
.shell-nav { width: 14rem; flex-shrink: 0; min-height: 0; }
.shell-pane { height: 100%; min-height: 0; min-width: 0; display: grid; grid-template-rows: auto minmax(0,1fr); }
.shell-main { flex: 1; }
.shell button:focus-visible { outline: var(--kui-focus-ring); }
@media (max-width:48rem) { .shell-body > * { width: 100%; flex: 1; } }
